package com.nexusdrive.metadata.service.impl;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.nexusdrive.metadata.entity.FileMetadata;import com.nexusdrive.metadata.repository.*;import java.util.Optional;import org.junit.jupiter.api.Test;class DeduplicationServiceImplTest{@Test void returnsActiveMatch(){var f=mock(FileMetadataRepository.class);var c=mock(ChunkRepository.class);var file=new FileMetadata();when(f.findFirstByContentHashAndStatus("hash",FileMetadata.Status.ACTIVE)).thenReturn(Optional.of(file));assertSame(file,new DeduplicationServiceImpl(f,c).findDuplicate("hash").orElseThrow());}}
